291	bool ProviderKeySetup::start_check(const SetupCredentials& credentials)
292	{
293	    if (busy() || credentials.api_key.empty() || !setup_provider_supported(credentials.provider))
294	        return false;
295	
296	    const std::string endpoint = credentials.endpoint.empty() ? m_endpoint_override : credentials.endpoint;
297	    AgentServicePtr   candidate = make_provider_agent(*profile_for(credentials.provider), credentials.api_key, credentials.model,
298	                                                      endpoint, m_transport_factory());
299	    if (!candidate->ready())
300	        return false;
301	
302	    m_started = m_clock();
303	    if (!candidate->start(probe_request()))
304	        return false;
305	    m_candidate = std::move(candidate);
306	    return true;
307	}
308	
309	void ProviderKeySetup::cancel()
310	{
311	    if (m_candidate)
312	        m_candidate->cancel();
313	    m_candidate.reset();
314	}
315	
316	std::optional<SetupOutcome> ProviderKeySetup::poll()
317	{
318	    if (!m_candidate)
319	        return std::nullopt;
320	
321	    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
322	        switch (event->kind) {
323	        case AgentEventKind::TextDelta:
324	            break; // What it says is irrelevant; that it answers is the test.
325	        case AgentEventKind::ToolCall:
326	        case AgentEventKind::Completed:
327	            // Either way the provider accepted the credentials and replied.
328	            return finish_ok();
329	        case AgentEventKind::Failed: {
330	            SetupOutcome outcome;
331	            outcome.error =
332	                event->error.value_or(AgentError{"setup_failed", "The provider did not answer.", true});
333	            outcome.elapsed_ms = elapsed_ms();
334	            cancel();
335	            return outcome;
336	        }
337	        }
338	    }
339	    return std::nullopt;
340	}
341	
342	bool ProviderKeySetup::commit(const SetupCredentials& credentials)
343	{
344	    return m_commit && m_commit(credentials);
345	}
346	
347	std::vector<SavedKey> ProviderKeySetup::saved_keys() const
348	{
349	    std::vector<SavedKey> saved;
350	    if (!m_keys.load)
351	        return saved;
352	    for (const ProviderProfile& profile : provider_profiles()) {
353	        const std::string key = m_keys.load(profile.id);
354	        if (!key.empty())
355	            saved.push_back(SavedKey{profile.id, api_key_hint(profile.id, key)});
356	    }
357	    return saved;
358	}
359	
360	bool ProviderKeySetup::remove_key(const std::string& provider)
361	{
362	    return setup_provider_supported(provider) && m_keys.remove && m_keys.remove(provider);
363	}
364	
365	int ProviderKeySetup::elapsed_ms() const
366	{
367	    return static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(m_clock() - m_started).count());
368	}
369	
370	SetupOutcome ProviderKeySetup::finish_ok()
371	{
372	    SetupOutcome outcome;
373	    outcome.ok         = true;
374	    outcome.elapsed_ms = elapsed_ms();
375	    // Drop the probe turn so the verified service is handed over idle, with
376	    // no partial response left for the user's first real message to inherit.
377	    m_candidate->cancel();
378	    outcome.service = std::move(m_candidate);
379	    m_candidate.reset();
380	    return outcome;
381	}
