626	        settings.model    = config->get(kSection, "model");
627	    }
628	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
629	    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, logging_listeners());
630	    runtime.setup        = make_agent_setup(config);
