#pragma once

// A model provider as data: which API family it speaks, where, how it is
// authenticated, which model it is given by default, what it is called in
// the errors shown to the person, and any fixed headers it wants. The turn
// loop (ProviderAgent) and the codecs read it; the table below is the only
// place a provider's name decides anything.

#include "AgentTransport.hpp"

#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// The wire format a provider speaks; one codec per family.
enum class ProviderFamily { Responses, Anthropic };

// How the API key travels: `Authorization: Bearer <key>`, or `x-api-key: <key>`.
enum class AuthStyle { Bearer, ApiKeyHeader };

struct ProviderProfile
{
    std::string    id;
    ProviderFamily family{ProviderFamily::Responses};
    std::string    endpoint;
    AuthStyle      auth{AuthStyle::Bearer};
    // The provider's default; a configured model replaces it in the copy the
    // agent is built with.
    std::string    model;
    // In the error text, as in "The OpenAI API key was rejected".
    std::string    display_name;
    // Sent on every request, after the credential.
    std::vector<AgentHttpHeader> headers;
    // The most output tokens one response may use, for a family that
    // requires the number (Anthropic); 0 where none is sent.
    unsigned       max_tokens{0};
    // How hard the model thinks before a reply, chosen per chat: one of the
    // levels the provider's model list offers for this model ("low",
    // "medium", "high", ...). Empty sends nothing, so the model's own default
    // applies. Title requests never carry it.
    std::string    effort;
};

// Every provider this build can talk to, in the order setup lists them.
inline const std::vector<ProviderProfile>& provider_profiles()
{
    static const std::vector<ProviderProfile> rows{
        {"openai", ProviderFamily::Responses, "https://api.openai.com/v1/responses", AuthStyle::Bearer, "gpt-5.4-mini", "OpenAI", {}, 0},
        // OpenRouter serves the Responses API. The default is the model the
        // OpenAI row uses, so the behaviour is the one already evaluated.
        // X-Title names the app in OpenRouter's usage pages. OpenRouter
        // also reads HTTP-Referer, the app's website, to give it a page of
        // its own; this build has no website constant to send, so it sends
        // none.
        {"openrouter", ProviderFamily::Responses, "https://openrouter.ai/api/v1/responses", AuthStyle::Bearer,
         "openai/gpt-5.4-mini", "OpenRouter", {{"X-Title", "JusPrin"}}, 0},
        // The Messages API. max_tokens is required there and also bounds the
        // model's thinking, which this model cannot turn off; 64000 is the
        // value Anthropic suggests for streaming requests.
        {"anthropic", ProviderFamily::Anthropic, "https://api.anthropic.com/v1/messages", AuthStyle::ApiKeyHeader,
         "claude-opus-5-5", "Anthropic", {{"anthropic-version", "2023-06-01"}}, 64000},
    };
    return rows;
}

// The row for a provider id, or null when this build has none.
inline const ProviderProfile* profile_for(const std::string& id)
{
    for (const ProviderProfile& profile : provider_profiles())
        if (profile.id == id)
            return &profile;
    return nullptr;
}

inline const ProviderProfile& openai_profile() { return *profile_for("openai"); }

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

// Provider credential setup for the Agent dock.
//
// Verifying a key and building the service that will use it are the same act
// here: the check runs one real request through the provider adapter the
// Agent goes on to use, so a key that passes is a key the Agent is already
// talking through, and the round-trip the user is shown is the one that
// actually happened. Nothing separate has to be kept in sync with it.
//
// GUI-free and poll-driven, mirroring IAgentService: transport callbacks only
// queue work, and the owner releases outcomes from poll() on the GUI thread.
// Persistence is injected, so this file never reaches AppConfig and stays
// linkable into the GUI-free contract tests.

#include "AgentService.hpp"
#include "AgentTransport.hpp"

#include <chrono>
#include <functional>
#include <memory>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

struct SetupCredentials
{
    std::string provider; // a provider_profiles() id
    std::string api_key;
    std::string model;    // optional; empty keeps the adapter's default
    std::string endpoint; // optional; empty keeps the adapter's default
};

// What the setup screen may know about a stored key: that there is one, and
// a hint to tell it apart from another. The key itself never leaves the host.
struct SavedKey
{
    std::string provider; // a provider_profiles() id
    std::string hint;     // api_key_hint()
};

struct SetupOutcome
{
    bool            ok{false};
    AgentError      error;      // set when !ok
    int             elapsed_ms{0};
    AgentServicePtr service;    // set when ok: verified, idle, ready to install
};

class IAgentSetupService
{
public:
    virtual ~IAgentSetupService() = default;

    virtual bool busy() const = 0;

    // Begins one verification. False when a check is already running, the
    // credentials are incomplete, or this build has no adapter for the
    // provider.
    virtual bool start_check(const SetupCredentials& credentials) = 0;
    virtual void cancel() = 0;

    // Releases at most one finished outcome; called from the owner's tick.
    virtual std::optional<SetupOutcome> poll() = 0;

    // Persists credentials that have just been verified. Reports failure
    // rather than pretending: a key that was not stored is a key the user
    // will have to enter again next launch, and they are told so.
    virtual bool commit(const SetupCredentials& credentials) = 0;

    // Every provider with a stored key, in provider_profiles() order.
    virtual std::vector<SavedKey> saved_keys() const = 0;

    // Deletes one provider's stored key. False when there was none or it
    // could not be removed.
    virtual bool remove_key(const std::string& provider) = 0;
};

using AgentSetupServicePtr = std::shared_ptr<IAgentSetupService>;

// Providers this build can verify. The page offers the same list; the host
// checks anyway, so a page/host mismatch fails visibly instead of hanging.
bool setup_provider_supported(const std::string& provider);

// A stored key as the setup screen shows it, "sk-ant-…a3F9": the fixed start
// the provider gives every key of its kind, then the last 4 characters. A key
// with no known start shows only its end, and one too short to spare 4
// characters shows none of them.
std::string api_key_hint(const std::string& provider, const std::string& key);

class ProviderKeySetup final : public IAgentSetupService
{
public:
    using TransportFactory = std::function<std::unique_ptr<IAgentHttpTransport>()>;
    using CommitFn         = std::function<bool(const SetupCredentials&)>;
    // Reads one provider's stored key ("" when none) and deletes it.
    struct KeyStore
    {
        std::function<std::string(const std::string& provider)> load;
        std::function<bool(const std::string& provider)>        remove;
    };
    using Clock            = std::function<std::chrono::steady_clock::time_point()>;

    // endpoint_override redirects the check the way JUSPRIN_AGENT_ENDPOINT
    // redirects the live Agent (agent_endpoint_override()), so a developer or
    // a harness can point setup at a stand-in instead of the real provider.
    ProviderKeySetup(TransportFactory transport,
                     CommitFn         commit,
                     KeyStore         keys              = {},
                     std::string      endpoint_override = {},
                     Clock            clock             = {});
    ~ProviderKeySetup() override;

    bool                        busy() const override { return m_candidate != nullptr; }
    bool                        start_check(const SetupCredentials& credentials) override;
    void                        cancel() override;
    std::optional<SetupOutcome> poll() override;
    bool                        commit(const SetupCredentials& credentials) override;
    std::vector<SavedKey>       saved_keys() const override;
    bool                        remove_key(const std::string& provider) override;

private:
    int          elapsed_ms() const;
    SetupOutcome finish_ok();

    TransportFactory                      m_transport_factory;
    CommitFn                              m_commit;
    KeyStore                              m_keys;
    std::string                           m_endpoint_override;
    Clock                                 m_clock;
    AgentServicePtr                       m_candidate;
    std::chrono::steady_clock::time_point m_started{};
};

} // namespace Slic3r::GUI::JusPrin::Agent
#include "AgentSetup.hpp"
#include "ProviderFactory.hpp"

#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

// The probe deliberately carries no project. A provider the user has not
// chosen yet must not receive their workspace merely to prove that a key
// works, so the request is a fixed sentence with an empty snapshot.
AgentRequest probe_request()
{
    AgentRequest request;
    request.request_id = "setup-key-check";
    request.user_text  = "Reply with the single word: ready.";
    return request;
}

// The fixed starts each provider gives its keys, longer ones first. They say
// what kind of key it is, not which one.
const std::vector<std::string>& key_prefixes(const std::string& provider)
{
    static const std::vector<std::string> anthropic{"sk-ant-"};
    static const std::vector<std::string> openai{"sk-proj-", "sk-svcacct-", "sk-admin-", "sk-"};
    static const std::vector<std::string> openrouter{"sk-or-v1-", "sk-or-"};
    static const std::vector<std::string> none;
    if (provider == "anthropic")
        return anthropic;
    if (provider == "openai")
        return openai;
    if (provider == "openrouter")
        return openrouter;
    return none;
}

// Keys shorter than this past their start keep their end to themselves too:
// 4 characters of a short key would be a large part of it.
constexpr std::size_t kMinHiddenForTail = 8;
constexpr std::size_t kTailLength       = 4;
constexpr const char* kEllipsis         = "\xE2\x80\xA6"; // U+2026

} // namespace

std::string api_key_hint(const std::string& provider, const std::string& key)
{
    std::string prefix;
    for (const std::string& candidate : key_prefixes(provider))
        if (key.size() > candidate.size() && key.compare(0, candidate.size(), candidate) == 0) {
            prefix = candidate;
            break;
        }
    std::string hint = prefix + kEllipsis;
    if (key.size() >= prefix.size() + kMinHiddenForTail + kTailLength)
        hint += key.substr(key.size() - kTailLength);
    return hint;
}

bool setup_provider_supported(const std::string& provider) { return profile_for(provider) != nullptr; }

ProviderKeySetup::ProviderKeySetup(TransportFactory transport,
                                   CommitFn         commit,
                                   KeyStore         keys,
                                   std::string      endpoint_override,
                                   Clock            clock)
    : m_transport_factory(std::move(transport)), m_commit(std::move(commit)), m_keys(std::move(keys)),
      m_endpoint_override(std::move(endpoint_override)), m_clock(std::move(clock))
{
    if (!m_clock)
        m_clock = []() { return std::chrono::steady_clock::now(); };
}

ProviderKeySetup::~ProviderKeySetup() = default;

bool ProviderKeySetup::start_check(const SetupCredentials& credentials)
{
    if (busy() || credentials.api_key.empty() || !setup_provider_supported(credentials.provider))
        return false;

    const std::string endpoint = credentials.endpoint.empty() ? m_endpoint_override : credentials.endpoint;
    AgentServicePtr   candidate = make_provider_agent(*profile_for(credentials.provider), credentials.api_key, credentials.model,
                                                      endpoint, m_transport_factory());
    if (!candidate->ready())
        return false;

    m_started = m_clock();
    if (!candidate->start(probe_request()))
        return false;
    m_candidate = std::move(candidate);
    return true;
}

void ProviderKeySetup::cancel()
{
    if (m_candidate)
        m_candidate->cancel();
    m_candidate.reset();
}

std::optional<SetupOutcome> ProviderKeySetup::poll()
{
    if (!m_candidate)
        return std::nullopt;

    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
        switch (event->kind) {
        case AgentEventKind::TextDelta:
            break; // What it says is irrelevant; that it answers is the test.
        case AgentEventKind::ToolCall:
        case AgentEventKind::Completed:
            // Either way the provider accepted the credentials and replied.
            return finish_ok();
        case AgentEventKind::Failed: {
            SetupOutcome outcome;
            outcome.error =
                event->error.value_or(AgentError{"setup_failed", "The provider did not answer.", true});
            outcome.elapsed_ms = elapsed_ms();
            cancel();
            return outcome;
        }
        }
    }
    return std::nullopt;
}

bool ProviderKeySetup::commit(const SetupCredentials& credentials)
{
    return m_commit && m_commit(credentials);
}

std::vector<SavedKey> ProviderKeySetup::saved_keys() const
{
    std::vector<SavedKey> saved;
    if (!m_keys.load)
        return saved;
    for (const ProviderProfile& profile : provider_profiles()) {
        const std::string key = m_keys.load(profile.id);
        if (!key.empty())
            saved.push_back(SavedKey{profile.id, api_key_hint(profile.id, key)});
    }
    return saved;
}

bool ProviderKeySetup::remove_key(const std::string& provider)
{
    return setup_provider_supported(provider) && m_keys.remove && m_keys.remove(provider);
}

int ProviderKeySetup::elapsed_ms() const
{
    return static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(m_clock() - m_started).count());
}

SetupOutcome ProviderKeySetup::finish_ok()
{
    SetupOutcome outcome;
    outcome.ok         = true;
    outcome.elapsed_ms = elapsed_ms();
    // Drop the probe turn so the verified service is handed over idle, with
    // no partial response left for the user's first real message to inherit.
    m_candidate->cancel();
    outcome.service = std::move(m_candidate);
    m_candidate.reset();
    return outcome;
}

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

// Building an Agent service from a provider row. GUI-free: setup and the
// runtime configuration both come through here, and so do the contract
// tests, which cannot link AppConfig.

#include "AgentConfiguration.hpp"
#include "ProviderAgent.hpp"
#include "ProviderProfile.hpp"

#include <functional>
#include <memory>
#include <string>

namespace Slic3r::GUI::JusPrin::Agent {

struct ProviderListeners
{
    std::function<void(const AgentUsage&)> usage;
    std::function<void(const std::string&, const std::string&, const std::string&)> refusal;
};

// The agent for a provider, with the codec its family speaks. An empty model
// or endpoint keeps the row's default.
AgentServicePtr make_provider_agent(const ProviderProfile&                profile,
                                    const std::string&                    api_key,
                                    const std::string&                    model,
                                    const std::string&                    endpoint,
                                    std::unique_ptr<IAgentHttpTransport>  transport,
                                    ProviderListeners                     listeners = {});

// Where a developer or a harness points the Agent instead of the provider:
// JUSPRIN_AGENT_ENDPOINT, or its older name JUSPRIN_OPENAI_ENDPOINT. It
// applies to whichever provider is in use. Empty when neither is set.
std::string agent_endpoint_override();

// The Agent choices AppConfig holds, read by AgentConfiguration.cpp.
struct AgentSettings
{
    bool        enabled{false};
    bool        cloud_consent{false};
    std::string provider; // empty means openai
    std::string api_key;  // the stored "<provider>_api_key"
    std::string model;    // empty keeps the provider's default
};

// The runtime those choices give: a ready service, or the reason there is
// none. `setup` is left for the caller to fill.
AgentRuntime resolve_agent_runtime(const AgentSettings&                                  settings,
                                   const std::string&                                    endpoint_override,
                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
                                   ProviderListeners                                     listeners = {});

} // namespace Slic3r::GUI::JusPrin::Agent
#include "ProviderFactory.hpp"
#include "AnthropicCodec.hpp"
#include "ResponsesCodec.hpp"

#include <cstdlib>
#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

std::unique_ptr<IProviderCodec> codec_for(ProviderFamily family)
{
    switch (family) {
    case ProviderFamily::Responses: return std::make_unique<ResponsesCodec>();
    case ProviderFamily::Anthropic: return std::make_unique<AnthropicCodec>();
    }
    return nullptr;
}

std::string environment(const char* name)
{
    const char* value = std::getenv(name);
    return value == nullptr ? std::string() : std::string(value);
}

} // namespace

AgentServicePtr make_provider_agent(const ProviderProfile&               profile,
                                    const std::string&                   api_key,
                                    const std::string&                   model,
                                    const std::string&                   endpoint,
                                    std::unique_ptr<IAgentHttpTransport> transport,
                                    ProviderListeners                    listeners)
{
    ProviderAgentConfig config;
    config.profile = profile;
    if (!model.empty())
        config.profile.model = model;
    if (!endpoint.empty())
        config.profile.endpoint = endpoint;
    config.api_key          = api_key;
    config.usage_listener   = std::move(listeners.usage);
    config.refusal_listener = std::move(listeners.refusal);
    return std::make_unique<ProviderAgent>(std::move(config), codec_for(profile.family), std::move(transport));
}

std::string agent_endpoint_override()
{
    if (std::string endpoint = environment("JUSPRIN_AGENT_ENDPOINT"); !endpoint.empty())
        return endpoint;
    return environment("JUSPRIN_OPENAI_ENDPOINT");
}

AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
                                   const std::string&                                           endpoint_override,
                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
                                   ProviderListeners                                            listeners)
{
    AgentRuntime runtime;
    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
    if (!settings.enabled) {
        runtime.unavailable_reason = "The Agent is not enabled.";
        return runtime;
    }
    const ProviderProfile* profile = profile_for(runtime.provider);
    if (profile == nullptr) {
        runtime.unavailable_reason = "The configured Agent provider is not supported.";
        return runtime;
    }
    if (!settings.cloud_consent) {
        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
        return runtime;
    }
    if (settings.api_key.empty()) {
        runtime.unavailable_reason = "No " + profile->display_name + " API key is configured.";
        return runtime;
    }
    runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
                                          std::move(listeners));
    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
    if (runtime.availability == AgentAvailability::Unavailable)
        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
    return runtime;
}

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

#include "AgentService.hpp"
#include "AgentSetup.hpp"

#include <functional>
#include <memory>
#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Agent {

class IChatModelSource;

struct AgentRuntime
{
    AgentServicePtr      service;
    AgentAvailability    availability{AgentAvailability::Unavailable};
    std::string          provider;
    std::string          unavailable_reason;
    // Verifies and stores credentials entered in the Agent dock. Always
    // present: setup is what an unconfigured build offers.
    AgentSetupServicePtr setup;
};

// Reads the Agent's choices and provider key from AppConfig. Project/recovery
// state never receives credentials.
AgentRuntime load_agent_runtime(AppConfig* config);

// Shared provider credential lookup for bounded, non-conversational features
// such as printer recognition. The key is an AppConfig item, "<provider>_api_key"
// in the Agent section, rather than an OS credential-store entry: macOS asks
// for the login password whenever a differently signed build reads a Keychain
// entry, which every unsigned rebuild is.
std::string load_provider_api_key(const AppConfig* config, const std::string& provider);

// The setup service the Agent dock drives: it verifies a candidate key
// against the live provider and, on success, stores it and records the
// non-secret choices load_agent_runtime() reads on the next launch.
AgentSetupServicePtr make_agent_setup(AppConfig* config);

// The docked Agent's per-chat models: every provider with a stored key, the
// default provider setup recorded, agents built from those keys, and each
// provider's model list fetched from the provider. `post` runs a callback on
// the GUI thread; the lists arrive through it.
std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config,
                                                         std::function<void(std::function<void()>)> post);

} // namespace Slic3r::GUI::JusPrin::Agent
#include "AgentConfiguration.hpp"

#include "AgentHost.hpp"
#include "ModelCatalogFetch.hpp"
#include "OpenAIResponsesAgent.hpp"
#include "ProviderFactory.hpp"
#include "libslic3r/AppConfig.hpp"

#include <boost/log/trivial.hpp>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

constexpr const char* kSection = "jusprin_agent";

std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }

ProviderListeners logging_listeners()
{
    ProviderListeners listeners;
    // Refused tool calls never reach a card or the activity list; the log is
    // where a wrong call can be read afterwards.
    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
    };
    return listeners;
}

bool configured_true(const AppConfig* config, const char* key)
{
    if (config == nullptr)
        return false;
    const std::string value = config->get(kSection, key);
    return value == "true" || value == "1";
}

} // namespace

std::string load_provider_api_key(const AppConfig* config, const std::string& provider)
{
    return config == nullptr ? std::string() : config->get(kSection, api_key_item_for(provider));
}

AgentRuntime load_agent_runtime(AppConfig* config)
{
    AgentSettings settings;
    settings.enabled       = configured_true(config, "enabled");
    settings.cloud_consent = configured_true(config, "cloud_consent");
    if (config != nullptr) {
        settings.provider = config->get(kSection, "provider");
        settings.model    = config->get(kSection, "model");
    }
    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, logging_listeners());
    runtime.setup        = make_agent_setup(config);
    return runtime;
}

AgentSetupServicePtr make_agent_setup(AppConfig* config)
{
    // Committing is the only part of setup that touches the machine, so it
    // lives here rather than in the GUI-free probe. Reaching this point means
    // the user read what the dock says about the provider billing them and
    // about the key staying on this machine, and chose to continue: that is
    // the cloud consent load_agent_runtime() requires on the next launch.
    auto commit = [config](const SetupCredentials& credentials) {
        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
            return false;
        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
        config->set(kSection, "provider", credentials.provider);
        config->set(kSection, "enabled", "true");
        config->set(kSection, "cloud_consent", "true");
        if (!credentials.model.empty())
            config->set(kSection, "model", credentials.model);
        // Written now, not at the next routine save, so a crash after setup
        // does not lose a key the user was just told is stored.
        config->save();
        return true;
    };
    ProviderKeySetup::KeyStore keys;
    keys.load   = [config](const std::string& provider) { return load_provider_api_key(config, provider); };
    keys.remove = [config](const std::string& provider) {
        if (config == nullptr || load_provider_api_key(config, provider).empty())
            return false;
        config->erase(kSection, api_key_item_for(provider));
        // A chat without a choice of its own talks to the recorded provider;
        // once its key is gone, that is the first provider that still has one.
        if (config->get(kSection, "provider") == provider)
            for (const ProviderProfile& profile : provider_profiles())
                if (!load_provider_api_key(config, profile.id).empty()) {
                    config->set(kSection, "provider", profile.id);
                    break;
                }
        // Saved now, as a stored key is: the person was just told it is gone.
        config->save();
        return true;
    };
    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), std::move(keys),
                                              agent_endpoint_override());
}

namespace {

class AppConfigChatModelSource final : public IChatModelSource
{
public:
    AppConfigChatModelSource(AppConfig* config, std::function<void(std::function<void()>)> post)
        : m_config(config), m_post(std::move(post)), m_cancelled(std::make_shared<std::atomic<bool>>(false))
    {}
    // A list still on its way is dropped rather than delivered to a host
    // that is gone.
    ~AppConfigChatModelSource() override { *m_cancelled = true; }

    // Read each time: setup may have stored a key since the last turn.
    std::vector<std::string> configured_providers() const override
    {
        std::vector<std::string> providers;
        if (!configured_true(m_config, "enabled") || !configured_true(m_config, "cloud_consent"))
            return providers;
        for (const ProviderProfile& profile : provider_profiles())
            if (!load_provider_api_key(m_config, profile.id).empty())
                providers.push_back(profile.id);
        return providers;
    }

    std::string default_provider() const override
    {
        const std::string provider = m_config == nullptr ? std::string() : m_config->get(kSection, "provider");
        return provider.empty() ? "openai" : provider;
    }

    AgentServicePtr make_agent(const ChatModelChoice& choice) override
    {
        const ProviderProfile* row = profile_for(choice.provider);
        const std::string      key = load_provider_api_key(m_config, choice.provider);
        if (row == nullptr || key.empty())
            return nullptr;
        ProviderProfile profile = *row;
        profile.effort          = choice.effort;
        return make_provider_agent(profile, key, choice.model, agent_endpoint_override(), make_openai_http_transport(),
                                   logging_listeners());
    }

    void list_models(const std::string& provider, ModelsDone done) override
    {
        const ProviderProfile* profile = profile_for(provider);
        const std::string      key     = load_provider_api_key(m_config, provider);
        if (profile == nullptr || key.empty()) {
            done(false, {});
            return;
        }
        fetch_model_list(*profile, key, agent_endpoint_override(), m_cancelled,
                         [post = m_post, done = std::move(done), provider](ModelListResult result) {
                             if (!result.ok)
                                 BOOST_LOG_TRIVIAL(warning) << "Agent model list for " << provider << ": " << result.error;
                             post([done, result = std::move(result)]() mutable { done(result.ok, std::move(result.models)); });
                         });
    }

private:
    AppConfig*                                  m_config;
    std::function<void(std::function<void()>)>  m_post;
    std::shared_ptr<std::atomic<bool>>          m_cancelled;
};

} // namespace

std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config, std::function<void(std::function<void()>)> post)
{
    return std::make_shared<AppConfigChatModelSource>(config, std::move(post));
}

} // namespace Slic3r::GUI::JusPrin::Agent

