void AgentHost::send_setup_status(const std::string&               phase,
                                  const std::string&               correlation_id,
                                  std::optional<int>               elapsed_ms,
                                  const std::optional<AgentError>& error,
                                  const std::string&               warning)
{
    json payload{{"phase", phase}};
