export type HostMessageType =
  | 'hello_ack'
  | 'hello_reject'
  | 'state'
  | 'conversations_updated'
  | 'context'
  | 'appearance'
  | 'agent_status'
  | 'message_added'
  | 'assistant_started'
  | 'assistant_delta'
  | 'assistant_completed'
  | 'assistant_failed'
  | 'assistant_stopped'
  | 'tool_activity'
  | 'bridge_error'
  | 'attachment_updated'
  | 'setup_status'
  | 'mcp_catalog'
  | 'mcp_preview'
  | 'mcp_status'
  | 'change_added'
  | 'work_updated'
  | 'model_catalog'
  | 'chat_model'
  | 'printer_session'
  | 'settings_catalog'
  | 'confirm'
  | 'setup_keys'
  | 'preferences';

// A question the host asks before an action it cannot take back, drawn as
// the design system's Confirmation dialog: a calibration that saves and
// closes the open project. The answer goes back with its requestId.
export interface ConfirmPayload {
  requestId: string;
  title: string;
  body: string;
  confirm: string;
  cancel: string;
}

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  sessionId?: string;
  revision?: number;
  payload: T;
}

// 'note' is the host's own voice: a short factual line the native shell posts
// when it changes something the reader should see in the thread (a filament
// change, for example). It is never a turn -- no reply follows it, and the host never
// sends it to the model -- so it renders as a plain line, not a bubble.
export type MessageRole = 'user' | 'assistant' | 'note';
export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
export type AgentStatus = 'ready' | 'unavailable';
