        server.erase("access_token");
        if (!token.empty()) {
            json& agent = settings[kAgentSection];
            if (!agent.is_object())
                agent = json::object();
            agent[std::string(kAccountProvider) + "_api_key"] = token;
            agent["provider"]                               = kAccountProvider;
            agent["enabled"]                                = "true";
            agent["cloud_consent"]                          = "true";
            signed_in                                       = true;
        }
    }
    return settings;
}

